<template><section v-if="winner" class="result-page"><NavHeader title="今晚的最佳选择" :step="5" @back="router.push('/debate')" /><div class="winner-scene"><div class="winner-spotlight"></div><div class="laurel left">❧</div><div class="laurel right">❧</div><h2>今晚，就吃这一家。</h2><div class="winner-avatar"><CharacterAvatar :character="winner.character" state="happy" :name="winner.host" /></div><div class="podium"></div><div class="medal"><AppIcon name="trophy" :size="18" /></div><i v-for="(piece, i) in confetti" :key="i" class="confetti" :style="piece"></i></div><div class="result-content"><div class="winner-card"><h3>{{ winner.name }}</h3><p>{{ winner.cuisine }} <i>·</i> {{ winner.price ? `¥${winner.price} / 人` : '价格待确认' }} <i>·</i> {{ store.distance(winner.id) }} km</p><div class="chips"><span v-for="tag in winner.tags" :key="tag" class="chip green">{{ tag }}</span></div></div><div class="section-heading"><h2>为什么是 TA？</h2></div><button v-for="reason in reasons" :key="reason.title" class="reason" @click="showEvidence(reason.evidenceIds, reason.description)"><span class="reason-icon"><AppIcon :name="reason.icon" :size="19" /></span><span><b>{{ reason.title }}</b><small>{{ reason.description }}</small></span><AppIcon name="chevron" :size="15" /></button><button class="caveat" @click="showEvidence([winner.evidenceIds[2]!], winner.caveat)"><AppIcon name="info" :size="17" /><span><b>去之前，再确认一下</b><small>{{ winner.caveat }}</small></span><AppIcon name="chevron" :size="15" /></button></div><div class="bottom-action"><button class="btn btn-primary" @click="router.push(`/restaurant/${winner.id}`)">就选这家<AppIcon name="arrow" :size="20" /></button><button class="text-btn" @click="compareOpen = true">再比较一下</button><span></span><button class="text-btn" @click="router.push('/map')">回地图看看</button></div><EvidenceSheet :open="evidenceOpen" :ids="evidenceIds" :claim="claim" @close="evidenceOpen = false" /><ComparisonSheet :open="compareOpen" @close="compareOpen = false" /></section></template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useDiningStore } from '@/stores/dining'
import { recommendationReasons } from '@/lib/recommendation'
import NavHeader from '@/components/NavHeader.vue'
import CharacterAvatar from '@/components/CharacterAvatar.vue'
import AppIcon from '@/components/AppIcon.vue'
import EvidenceSheet from '@/components/EvidenceSheet.vue'
import ComparisonSheet from '@/components/ComparisonSheet.vue'
const store = useDiningStore(), router = useRouter(), winner = computed(() => store.winner), compareOpen = ref(false), evidenceOpen = ref(false), evidenceIds = ref<string[]>([]), claim = ref('')
const reasons = computed(() => winner.value ? recommendationReasons(winner.value, store.filters) : [])
const confetti = Array.from({ length: 15 }, (_, i) => ({ left: `${10 + (i * 37 % 80)}%`, top: `${35 + (i * 23 % 180)}px`, background: ['#c9483e', '#e3b04b', '#2f6e62', '#7a5a9e'][i % 4], transform: `rotate(${i * 47}deg)`, opacity: .3 + i % 3 * .15 }))
function showEvidence(ids: string[], text: string) { evidenceIds.value = ids; claim.value = text; evidenceOpen.value = true }
onMounted(() => { if (!store.decide()) { store.notify('目前没有选手符合最新条件，请重新筛选'); router.replace('/filter') } })
</script>
